7:         var accounts: [FinanceAccount] = []
8:         var accountOffset = 0
9:         var accountIDs: Set<String> = []
10:         while true {
11:             try Task.checkCancellation()
12:             let page = try await self.accounts(offset: accountOffset)
13:             accounts.append(contentsOf: page.items.filter { accountIDs.insert($0.id).inserted })
14:             guard accounts.count <= 10_000 else { throw APIClientError.invalidResponse }
15:             guard page.hasMore else { break }
16:             guard let next = page.nextOffset, next > accountOffset, next <= 10_000, accounts.count < 10_000 else {
17:                 throw APIClientError.invalidResponse
18:             }
19:             accountOffset = next
20:         }
21:         var entries: [FinanceTransaction] = []
22:         for month in period.months {
23:             var offset = 0
24:             while true {
25:                 try Task.checkCancellation()
26:                 let page = try await transactions(month: month, type: .all, accountID: nil, query: "", offset: offset)
27:                 entries.append(contentsOf: page.items)
28:                 guard entries.count <= 100_000 else { throw APIClientError.invalidResponse }
29:                 guard page.hasMore else { break }
30:                 guard let next = page.nextOffset, next > offset, next <= 100_000 else {
31:                     throw APIClientError.invalidResponse
32:                 }
33:                 offset = next
34:             }
35:         }
36:         try Task.checkCancellation()
37:         return try FinanceInsights(period: period, entries: entries, accounts: accounts)
38:     }
