22: /**
23:  * 在一个只读入口内组合日历、资料、财务与学习的既有统计口径。
24:  *
25:  * <p>调用方只需提供用户、自然日和时区，不需要了解各领域的查询细节。</p>
26:  */
27: @Service
28: @RequiredArgsConstructor
29: public class DailyInsightService {
30:     private final DailyEventService dailyEventService;
31:     private final RecordService recordService;
32:     private final ExpenseAnalyticsService expenseAnalyticsService;
33:     private final StudyService studyService;
34: 
35:     /** 返回指定自然日的活动汇总，不调用模型且不写入业务数据。 */
36:     @Transactional(readOnly = true)
37:     public DailyInsight getDailyInsight(String ownerId, LocalDate date, ZoneId timezone) {
38:         if (ownerId == null || ownerId.isBlank()) throw new IllegalArgumentException("用户不能为空");
39:         if (date == null || timezone == null) throw new IllegalArgumentException("日期与时区不能为空");
40: 
41:         List<DailyEvent> events = dailyEventService.getDay(ownerId, date).events();
42:         List<TodoDetails> todos = events.stream()
43:                 .filter(event -> "todo".equals(event.eventType()))
44:                 .map(DailyEvent::details)
45:                 .filter(TodoDetails.class::isInstance)
46:                 .map(TodoDetails.class::cast)
47:                 .toList();
48:         int completedTodos = (int) todos.stream().filter(TodoDetails::completed).count();
49:         int scheduleCount = (int) events.stream().filter(event -> "schedule".equals(event.eventType())).count();
50:         int expenseCount = (int) events.stream().filter(event -> "expense".equals(event.eventType())).count();
51: 
52:         int recordCount = recordService.summarizeDays(ownerId, date, date).stream()
53:                 .findFirst().map(summary -> summary.count()).orElse(0);
54:         var expenseDay = expenseAnalyticsService.analyze(ownerId, date, date).days().getFirst();
55:         var study = studyService.getStatistics(ownerId, date, date, timezone);
56: 
57:         return new DailyInsight(date,
58:                 new TodoSummary(todos.size(), completedTodos, todos.size() - completedTodos),
59:                 scheduleCount,
60:                 new RecordSummary(recordCount),
61:                 new FinanceSummary(expenseCount, expenseDay.total(), expenseDay.categories()),
62:                 new StudySummary(study.totalDurationSeconds(), study.sessionCount()));
63:     }
64: }

