package butvan.agent.network.mobiletask.model;

import java.time.Instant;
import java.util.List;

/** 手机端本地通知提醒领域模型。 */
public final class MobileTaskModels {

    private MobileTaskModels() {
    }

    /** 一条手机端本地通知提醒配置。 */
    public record MobileTask(
            String id,
            String title,
            String body,
            String recurrence,
            int hour,
            int minute,
            Integer weekday,
            Integer dayOfMonth,
            String onceDate,
            String timeZone,
            boolean enabled,
            long version) {
    }

    /** 客户端上报的系统通知送达观察回执。 */
    public record MobileTaskDelivery(String id, Instant deliveredAt) {
    }

    /** 统一分页结构。 */
    public record PageResult<T>(List<T> items, Integer nextOffset, boolean hasMore) {
    }
}

package butvan.agent.network.mobiletask.dto;

import butvan.agent.network.mobiletask.model.MobileTaskModels.MobileTask;
import butvan.agent.network.mobiletask.model.MobileTaskModels.MobileTaskDelivery;
import butvan.agent.network.mobiletask.model.MobileTaskModels.PageResult;

import java.time.Instant;
import java.util.List;

/** 手机端通知任务 HTTP 请求与响应 DTO。 */
public final class MobileTaskDtos {

    private MobileTaskDtos() {
    }

    /** 创建或更新手机通知任务请求。 */
    public record SaveMobileTaskRequest(
            String id,
            String title,
            String body,
            String recurrence,
            int hour,
            int minute,
            Integer weekday,
            Integer dayOfMonth,
            String onceDate,
            String timeZone,
            boolean enabled,
            long version) {
    }

    /** 上报系统本地通知送达回执请求。 */
    public record RecordDeliveryRequest(String eventId, Instant deliveredAt) {
    }

    /** 手机通知任务响应。 */
    public record MobileTaskResponse(
            String id,
            String title,
            String body,
            String recurrence,
            int hour,
            int minute,
            Integer weekday,
            Integer dayOfMonth,
            String onceDate,
            String timeZone,
            boolean enabled,
            long version) {
    }

    /** 通知送达观察回执响应。 */
    public record MobileTaskDeliveryResponse(String id, Instant deliveredAt) {
    }

    /** 分页响应。 */
    public record PageResponse<T>(List<T> items, Integer nextOffset, boolean hasMore) {
    }

    public static MobileTaskResponse from(MobileTask task) {
        return new MobileTaskResponse(
                task.id(), task.title(), task.body(), task.recurrence(),
                task.hour(), task.minute(), task.weekday(), task.dayOfMonth(),
                task.onceDate(), task.timeZone(), task.enabled(), task.version());
    }

    public static MobileTaskDeliveryResponse from(MobileTaskDelivery delivery) {
        return new MobileTaskDeliveryResponse(delivery.id(), delivery.deliveredAt());
    }

    public static PageResponse<MobileTaskResponse> fromTasks(PageResult<MobileTask> page) {
        return new PageResponse<>(page.items().stream().map(MobileTaskDtos::from).toList(),
                page.nextOffset(), page.hasMore());
    }

    public static PageResponse<MobileTaskDeliveryResponse> fromDeliveries(PageResult<MobileTaskDelivery> page) {
        return new PageResponse<>(page.items().stream().map(MobileTaskDtos::from).toList(),
                page.nextOffset(), page.hasMore());
    }
}

package butvan.agent.network.mobiletask.repository;

import butvan.agent.network.mobiletask.model.MobileTaskModels.MobileTask;
import butvan.agent.network.mobiletask.model.MobileTaskModels.MobileTaskDelivery;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/** 手机端通知任务 SQLite 持久化访问。 */
@Repository
@RequiredArgsConstructor
public class MobileTaskRepository {

    private final JdbcTemplate jdbcTemplate;

    public List<MobileTask> findPage(String ownerId, String query, Boolean enabled, int offset, int limit) {
        StringBuilder sql = new StringBuilder("""
                SELECT id, title, body, recurrence, hour, minute, weekday, day_of_month,
                       once_date, timezone, enabled, version
                FROM mobile_task
                WHERE owner_id = ?
                """);
        List<Object> args = new ArrayList<>();
        args.add(ownerId);
        if (enabled != null) {
            sql.append(" AND enabled = ?");
            args.add(enabled ? 1 : 0);
        }
        if (query != null && !query.isBlank()) {
            sql.append(" AND (LOWER(title) LIKE ? OR LOWER(body) LIKE ?)");
            String pattern = "%" + query.trim().toLowerCase() + "%";
            args.add(pattern);
            args.add(pattern);
        }
        sql.append(" ORDER BY enabled DESC, updated_at DESC, id ASC LIMIT ? OFFSET ?");
        args.add(limit);
        args.add(offset);
        return jdbcTemplate.query(sql.toString(), this::mapTask, args.toArray());
    }

    public List<MobileTask> findEnabled(String ownerId) {
        return jdbcTemplate.query("""
                SELECT id, title, body, recurrence, hour, minute, weekday, day_of_month,
                       once_date, timezone, enabled, version
                FROM mobile_task
                WHERE owner_id = ? AND enabled = 1
                ORDER BY updated_at DESC, id ASC
                """, this::mapTask, ownerId);
    }

    public Optional<MobileTask> findById(String ownerId, String id) {
        List<MobileTask> rows = jdbcTemplate.query("""
                SELECT id, title, body, recurrence, hour, minute, weekday, day_of_month,
                       once_date, timezone, enabled, version
                FROM mobile_task
                WHERE owner_id = ? AND id = ?
                """, this::mapTask, ownerId, id);
        return rows.stream().findFirst();
    }

    public void insert(String ownerId, MobileTask task, long nowEpochMillis) {
        jdbcTemplate.update("""
                INSERT INTO mobile_task(
                    id, owner_id, title, body, recurrence, hour, minute, weekday,
                    day_of_month, once_date, timezone, enabled, version, created_at, updated_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                task.id(), ownerId, task.title(), task.body(), task.recurrence(),
                task.hour(), task.minute(), task.weekday(), task.dayOfMonth(),
                task.onceDate(), task.timeZone(), task.enabled() ? 1 : 0,
                task.version(), nowEpochMillis, nowEpochMillis);
    }

    public int update(String ownerId, MobileTask task, long expectedVersion, long nowEpochMillis) {
        return jdbcTemplate.update("""
                UPDATE mobile_task
                SET title = ?, body = ?, recurrence = ?, hour = ?, minute = ?, weekday = ?,
                    day_of_month = ?, once_date = ?, timezone = ?, enabled = ?,
                    version = version + 1, updated_at = ?
                WHERE owner_id = ? AND id = ? AND version = ?
                """,
                task.title(), task.body(), task.recurrence(), task.hour(), task.minute(),
                task.weekday(), task.dayOfMonth(), task.onceDate(), task.timeZone(),
                task.enabled() ? 1 : 0, nowEpochMillis, ownerId, task.id(), expectedVersion);
    }

    public int delete(String ownerId, String id, long expectedVersion) {
        return jdbcTemplate.update("""
                DELETE FROM mobile_task
                WHERE owner_id = ? AND id = ? AND version = ?
                """, ownerId, id, expectedVersion);
    }

    public List<MobileTaskDelivery> findDeliveries(String ownerId, String taskId, int offset, int limit) {
        return jdbcTemplate.query("""
                SELECT id, delivered_at
                FROM mobile_task_delivery
                WHERE owner_id = ? AND task_id = ?
                ORDER BY delivered_at DESC, id ASC
                LIMIT ? OFFSET ?
                """,
                (rs, rowNum) -> new MobileTaskDelivery(
                        rs.getString("id"),
                        Instant.ofEpochMilli(rs.getLong("delivered_at"))),
                ownerId, taskId, limit, offset);
    }

    public void insertDeliveryIgnoreDuplicate(
            String id, String ownerId, String taskId, String eventId, Instant deliveredAt) {
        jdbcTemplate.update("""
                INSERT INTO mobile_task_delivery(id, task_id, owner_id, event_id, delivered_at)
                VALUES(?, ?, ?, ?, ?)
                ON CONFLICT(owner_id, task_id, event_id) DO NOTHING
                """, id, taskId, ownerId, eventId, deliveredAt.toEpochMilli());
    }

    private MobileTask mapTask(ResultSet rs, int rowNum) throws SQLException {
        Integer weekday = nullableInt(rs, "weekday");
        Integer dayOfMonth = nullableInt(rs, "day_of_month");
        return new MobileTask(
                rs.getString("id"),
                rs.getString("title"),
                rs.getString("body"),
                rs.getString("recurrence"),
                rs.getInt("hour"),
                rs.getInt("minute"),
                weekday,
                dayOfMonth,
                rs.getString("once_date"),
                rs.getString("timezone"),
                rs.getInt("enabled") == 1,
                rs.getLong("version"));
    }

    private Integer nullableInt(ResultSet rs, String column) throws SQLException {
        int val = rs.getInt(column);
        return rs.wasNull() ? null : val;
    }
}

package butvan.agent.network.mobiletask.service;

import butvan.agent.network.mobiletask.dto.MobileTaskDtos.SaveMobileTaskRequest;
import butvan.agent.network.mobiletask.model.MobileTaskModels.MobileTask;
import butvan.agent.network.mobiletask.model.MobileTaskModels.MobileTaskDelivery;
import butvan.agent.network.mobiletask.model.MobileTaskModels.PageResult;
import butvan.agent.network.mobiletask.repository.MobileTaskRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.DateTimeException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.time.format.DateTimeParseException;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.UUID;

/** 手机端通知任务业务逻辑与校验。 */
@Service
@RequiredArgsConstructor
public class MobileTaskService {

    private static final Set<String> RECURRENCES = Set.of("once", "daily", "weekly", "monthly");
    private static final int MAX_TITLE_LENGTH = 120;
    private static final int MAX_BODY_LENGTH = 500;
    private static final int MAX_PAGE_LIMIT = 100;

    private final MobileTaskRepository repository;

    @Transactional(readOnly = true)
    public PageResult<MobileTask> list(String ownerId, String query, Boolean enabled, int offset, int limit) {
        requireOwner(ownerId);
        int safeOffset = Math.max(0, offset);
        int safeLimit = Math.min(Math.max(1, limit), MAX_PAGE_LIMIT);
        List<MobileTask> rows = repository.findPage(ownerId, query, enabled, safeOffset, safeLimit + 1);
        boolean hasMore = rows.size() > safeLimit;
        List<MobileTask> items = hasMore ? rows.subList(0, safeLimit) : rows;
        return new PageResult<>(items, hasMore ? safeOffset + safeLimit : null, hasMore);
    }

    @Transactional(readOnly = true)
    public List<MobileTask> listEnabled(String ownerId) {
        requireOwner(ownerId);
        return repository.findEnabled(ownerId);
    }

    @Transactional(readOnly = true)
    public MobileTask get(String ownerId, String id) {
        requireOwner(ownerId);
        return repository.findById(ownerId, requireId(id))
                .orElseThrow(() -> new IllegalArgumentException("提醒任务不存在"));
    }

    @Transactional
    public MobileTask create(String ownerId, SaveMobileTaskRequest request) {
        requireOwner(ownerId);
        String id = request.id() == null || request.id().isBlank()
                ? UUID.randomUUID().toString()
                : request.id().trim();
        MobileTask task = validateAndBuild(id, request, 1L);
        repository.insert(ownerId, task, System.currentTimeMillis());
        return task;
    }

    @Transactional
    public MobileTask update(String ownerId, String id, SaveMobileTaskRequest request) {
        requireOwner(ownerId);
        String taskId = requireId(id);
        MobileTask existing = repository.findById(ownerId, taskId)
                .orElseThrow(() -> new IllegalArgumentException("提醒任务不存在"));
        MobileTask next = validateAndBuild(taskId, request, request.version() + 1);
        int updated = repository.update(ownerId, next, request.version(), System.currentTimeMillis());
        if (updated == 0) {
            throw new IllegalArgumentException("提醒任务已被其他设备更新（当前版本 " + existing.version() + "），请刷新后重试");
        }
        return get(ownerId, taskId);
    }

    @Transactional
    public void delete(String ownerId, String id, long version) {
        requireOwner(ownerId);
        String taskId = requireId(id);
        if (repository.findById(ownerId, taskId).isEmpty()) {
            throw new IllegalArgumentException("提醒任务不存在");
        }
        int deleted = repository.delete(ownerId, taskId, version);
        if (deleted == 0) {
            throw new IllegalArgumentException("提醒任务版本冲突，请刷新后重试");
        }
    }

    @Transactional(readOnly = true)
    public PageResult<MobileTaskDelivery> deliveries(String ownerId, String taskId, int offset, int limit) {
        requireOwner(ownerId);
        get(ownerId, taskId);
        int safeOffset = Math.max(0, offset);
        int safeLimit = Math.min(Math.max(1, limit), MAX_PAGE_LIMIT);
        List<MobileTaskDelivery> rows = repository.findDeliveries(ownerId, taskId, safeOffset, safeLimit + 1);
        boolean hasMore = rows.size() > safeLimit;
        List<MobileTaskDelivery> items = hasMore ? rows.subList(0, safeLimit) : rows;
        return new PageResult<>(items, hasMore ? safeOffset + safeLimit : null, hasMore);
    }

    @Transactional
    public void recordDelivery(String ownerId, String taskId, String eventId, Instant deliveredAt) {
        requireOwner(ownerId);
        get(ownerId, taskId);
        if (eventId == null || eventId.isBlank()) {
            throw new IllegalArgumentException("通知事件 ID 不能为空");
        }
        Instant timestamp = deliveredAt == null ? Instant.now() : deliveredAt;
        repository.insertDeliveryIgnoreDuplicate(
                UUID.randomUUID().toString(), ownerId, taskId, eventId.trim(), timestamp);
    }

    private MobileTask validateAndBuild(String id, SaveMobileTaskRequest req, long version) {
        if (req == null) throw new IllegalArgumentException("请求不能为空");
        String title = req.title() == null ? "" : req.title().trim();
        if (title.isEmpty() || title.length() > MAX_TITLE_LENGTH) {
            throw new IllegalArgumentException("提醒标题需在 1 到 120 个字符之间");
        }
        String body = req.body() == null ? "" : req.body().trim();
        if (body.length() > MAX_BODY_LENGTH) {
            throw new IllegalArgumentException("提醒正文不能超过 500 个字符");
        }
        String recurrence = req.recurrence() == null ? "" : req.recurrence().trim().toLowerCase(Locale.ROOT);
        if (!RECURRENCES.contains(recurrence)) {
            throw new IllegalArgumentException("不支持的重复周期");
        }
        if (req.hour() < 0 || req.hour() > 23 || req.minute() < 0 || req.minute() > 59) {
            throw new IllegalArgumentException("提醒时间不合法");
        }
        String tz = req.timeZone() == null || req.timeZone().isBlank() ? "Asia/Shanghai" : req.timeZone().trim();
        try {
            ZoneId.of(tz);
        } catch (DateTimeException exception) {
            throw new IllegalArgumentException("时区不合法");
        }
        Integer weekday = null;
        Integer dayOfMonth = null;
        String onceDate = null;
        switch (recurrence) {
            case "weekly" -> {
                if (req.weekday() == null || req.weekday() < 1 || req.weekday() > 7) {
                    throw new IllegalArgumentException("周提醒星期需在 1 到 7 之间");
                }
                weekday = req.weekday();
            }
            case "monthly" -> {
                if (req.dayOfMonth() == null || req.dayOfMonth() < 1 || req.dayOfMonth() > 28) {
                    throw new IllegalArgumentException("月提醒日期需在 1 到 28 日之间");
                }
                dayOfMonth = req.dayOfMonth();
            }
            case "once" -> {
                if (req.onceDate() == null || req.onceDate().isBlank()) {
                    throw new IllegalArgumentException("一次性提醒必须提供日期");
                }
                try {
                    LocalDate.parse(req.onceDate().trim());
                    onceDate = req.onceDate().trim();
                } catch (DateTimeParseException exception) {
                    throw new IllegalArgumentException("一次性提醒日期格式应为 YYYY-MM-DD");
                }
            }
            default -> {
            }
        }
        return new MobileTask(id, title, body, recurrence, req.hour(), req.minute(),
                weekday, dayOfMonth, onceDate, tz, req.enabled(), version);
    }

    private void requireOwner(String ownerId) {
        if (ownerId == null || ownerId.isBlank()) throw new IllegalArgumentException("用户不能为空");
    }

    private String requireId(String id) {
        if (id == null || id.isBlank()) throw new IllegalArgumentException("任务 ID 不能为空");
        return id.trim();
    }
}

package butvan.agent.network.mobiletask.controller;

import butvan.agent.agents.identity.CurrentUserProvider;
import butvan.agent.network.annotation.ApiLog;
import butvan.agent.network.common.Result;
import butvan.agent.network.mobiletask.dto.MobileTaskDtos;
import butvan.agent.network.mobiletask.dto.MobileTaskDtos.MobileTaskDeliveryResponse;
import butvan.agent.network.mobiletask.dto.MobileTaskDtos.MobileTaskResponse;
import butvan.agent.network.mobiletask.dto.MobileTaskDtos.PageResponse;
import butvan.agent.network.mobiletask.dto.MobileTaskDtos.RecordDeliveryRequest;
import butvan.agent.network.mobiletask.dto.MobileTaskDtos.SaveMobileTaskRequest;
import butvan.agent.network.mobiletask.service.MobileTaskService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

/** 手机端本地通知提醒任务 HTTP 协议适配层。 */
@RestController
@CrossOrigin(origins = "*")
@RequestMapping("/agent/mobile-tasks")
@RequiredArgsConstructor
public class MobileTaskController {

    private final MobileTaskService service;
    private final CurrentUserProvider currentUserProvider;

    @ApiLog("查询手机端提醒任务列表")
    @GetMapping
    public Result<PageResponse<MobileTaskResponse>> list(
            @RequestParam(defaultValue = "") String query,
            @RequestParam(required = false) Boolean enabled,
            @RequestParam(defaultValue = "0") int offset,
            @RequestParam(defaultValue = "50") int limit) {
        return Result.success(MobileTaskDtos.fromTasks(
                service.list(ownerId(), query, enabled, offset, limit)));
    }

    @ApiLog("查询已启用的手机端提醒任务")
    @GetMapping("/enabled")
    public Result<List<MobileTaskResponse>> enabled() {
        return Result.success(service.listEnabled(ownerId()).stream().map(MobileTaskDtos::from).toList());
    }

    @ApiLog("查询手机端提醒任务详情")
    @GetMapping("/{id}")
    public Result<MobileTaskResponse> get(@PathVariable String id) {
        return Result.success(MobileTaskDtos.from(service.get(ownerId(), id)));
    }

    @ApiLog("创建手机端提醒任务")
    @PostMapping
    public Result<MobileTaskResponse> create(@RequestBody SaveMobileTaskRequest request) {
        return Result.success(MobileTaskDtos.from(service.create(ownerId(), request)));
    }

    @ApiLog("更新手机端提醒任务")
    @PutMapping("/{id}")
    public Result<MobileTaskResponse> update(
            @PathVariable String id, @RequestBody SaveMobileTaskRequest request) {
        return Result.success(MobileTaskDtos.from(service.update(ownerId(), id, request)));
    }

    @ApiLog("删除手机端提醒任务")
    @DeleteMapping("/{id}")
    public Result<String> delete(@PathVariable String id, @RequestParam long version) {
        service.delete(ownerId(), id, version);
        return Result.success("手机提醒任务已删除");
    }

    @ApiLog("查询手机通知送达观察记录")
    @GetMapping("/{id}/deliveries")
    public Result<PageResponse<MobileTaskDeliveryResponse>> deliveries(
            @PathVariable String id,
            @RequestParam(defaultValue = "0") int offset,
            @RequestParam(defaultValue = "50") int limit) {
        return Result.success(MobileTaskDtos.fromDeliveries(
                service.deliveries(ownerId(), id, offset, limit)));
    }

    @ApiLog("记录手机通知送达观察回执")
    @PostMapping("/{id}/deliveries")
    public Result<String> recordDelivery(
            @PathVariable String id, @RequestBody RecordDeliveryRequest request) {
        service.recordDelivery(ownerId(), id, request.eventId(), request.deliveredAt());
        return Result.success("已记录送达回执");
    }

    private String ownerId() {
        return currentUserProvider.currentUserId();
    }
}

